			row[PkgPackageSchema.Constants.KP_Weight                    ] = (decimal)0;
			row[PkgPackageSchema.Constants.KP_WeightUQ                  ] = "";
			row[PkgPackageSchema.Constants.KP_Width                     ] = (decimal)0;
		}

